 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid LEFT JOIN pg_constraint con ON con.oid=t.tgconstraint
 WHERE t.tgrelid=ANY(ids) AND NOT t.tgisinternal;
 IF actual IS DISTINCT FROM '{"native_turn_frames:native_turn_frame_immutable":{"tgargs":"\\x","tgattr":[],"tgname":"native_turn_frame_immutable","tgqual":null,"tgtype":27,"tgnargs":0,"tgenabled":"O","tgnewtable":null,"tgoldtable":null,"tgparentid":"0","tgdeferrable":false,"tgisinternal":false,"tgconstrindid":"0","tgconstrrelid":"0","tginitdeferred":false,"function":"native_turn_frame_immutable()","constraint":null},"native_turn_frames:native_turn_frame_pair":{"tgargs":"\\x","tgattr":[],"tgname":"native_turn_frame_pair","tgqual":null,"tgtype":5,"tgnargs":0,"tgenabled":"O","tgnewtable":null,"tgoldtable":null,"tgparentid":"0","tgdeferrable":true,"tgisinternal":false,"tgconstrindid":"0","tgconstrrelid":"0","tginitdeferred":true,"function":"native_turn_validate_frame_pair()","constraint":"native_turn_frame_pair"},"native_turn_publication_debt:native_turn_completion_debt_guard":{"tgargs":"\\x","tgattr":[],"tgname":"native_turn_completion_debt_guard","tgqual":null,"tgtype":11,"tgnargs":0,"tgenabled":"O","tgnewtable":null,"tgoldtable":null,"tgparentid":"0","tgdeferrable":false,"tgisinternal":false,"tgconstrindid":"0","tgconstrrelid":"0","tginitdeferred":false,"function":"native_turn_guard_completion_debt()","constraint":null},"native_turn_publication_seals:application_field_derivation_dependencies":{"tgargs":"\\x","tgattr":[],"tgname":"application_field_derivation_dependencies","tgqual":null,"tgtype":5,"tgnargs":0,"tgenabled":"O","tgnewtable":null,"tgoldtable":null,"tgparentid":"0","tgdeferrable":true,"tgisinternal":false,"tgconstrindid":"0","tgconstrrelid":"0","tginitdeferred":true,"function":"native_turn_complete_publication()","constraint":"application_field_derivation_dependencies"}}'::jsonb OR EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid
  WHERE t.tgrelid=ANY(ids) AND NOT t.tgisinternal AND p.pronamespace<>'public'::regnamespace)
 THEN RAISE EXCEPTION 'native_annotation_publication_triggers_changed';END IF;
 -- Authenticate all FK trigger bindings, including referenced-side triggers.
 IF EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=ANY(ids) AND t.tgisinternal
   AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.oid=t.tgconstraint AND c.contype='f' AND c.conrelid=ANY(ids)))
  OR EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid=ANY(ids) AND c.contype='f' AND (
   (SELECT count(*) FROM pg_trigger t WHERE t.tgconstraint=c.oid)<>4 OR EXISTS(
    SELECT 1 FROM pg_trigger t WHERE t.tgconstraint=c.oid AND (
     NOT t.tgisinternal OR t.tgenabled<>'O' OR t.tgnargs<>0 OR t.tgargs<>''::bytea OR t.tgattr<>''::int2vector
     OR t.tgqual IS NOT NULL OR t.tgoldtable IS NOT NULL OR t.tgnewtable IS NOT NULL OR t.tgparentid<>0
     OR t.tgconstrindid<>c.conindid OR t.tgconstrrelid<>CASE WHEN t.tgrelid=c.conrelid THEN c.confrelid ELSE c.conrelid END
     OR NOT(
      t.tgrelid=c.conrelid AND t.tgdeferrable=c.condeferrable AND t.tginitdeferred=c.condeferred
       AND (t.tgtype=5 AND t.tgfoid='pg_catalog."RI_FKey_check_ins"()'::regprocedure
        OR t.tgtype=17 AND t.tgfoid='pg_catalog."RI_FKey_check_upd"()'::regprocedure)
      OR t.tgrelid=c.confrelid AND (
       t.tgtype=17 AND t.tgfoid='pg_catalog."RI_FKey_noaction_upd"()'::regprocedure
        AND t.tgdeferrable=c.condeferrable AND t.tginitdeferred=c.condeferred
       OR t.tgtype=9 AND (c.confdeltype='c' AND t.tgfoid='pg_catalog."RI_FKey_cascade_del"()'::regprocedure AND NOT t.tgdeferrable AND NOT t.tginitdeferred
        OR c.confdeltype='a' AND t.tgfoid='pg_catalog."RI_FKey_noaction_del"()'::regprocedure AND t.tgdeferrable=c.condeferrable AND t.tginitdeferred=c.condeferred)))))))
 THEN RAISE EXCEPTION 'native_annotation_publication_fk_trigger_changed';END IF;
 EXECUTE 'SELECT jsonb_build_object(
 ''tables'',(SELECT jsonb_agg(jsonb_build_object(''oid'',c.oid,''owner'',c.relowner,''kind'',c.relkind,''persistence'',c.relpersistence,''rls'',c.relrowsecurity,''forceRls'',c.relforcerowsecurity,''acl'',c.relacl) ORDER BY c.oid)
 FROM pg_class c WHERE c.oid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''columns'',(SELECT jsonb_agg(jsonb_build_array(attrelid,attnum,attname,atttypid,atttypmod,attnotnull,attidentity,attgenerated,attisdropped,attacl) ORDER BY attrelid,attnum)
 FROM pg_attribute WHERE attnum>0 AND attrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''triggers'',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE tgrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''constraints'',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE conrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''rules'',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE ev_class=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''defaults'',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d WHERE adrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''policies'',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE polrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])))' INTO table_capture;
 expected_body:='SELECT (SELECT ('||'SELECT jsonb_build_object(
 ''tables'',(SELECT jsonb_agg(jsonb_build_object(''oid'',c.oid,''owner'',c.relowner,''kind'',c.relkind,''persistence'',c.relpersistence,''rls'',c.relrowsecurity,''forceRls'',c.relforcerowsecurity,''acl'',c.relacl) ORDER BY c.oid)
 FROM pg_class c WHERE c.oid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''columns'',(SELECT jsonb_agg(jsonb_build_array(attrelid,attnum,attname,atttypid,atttypmod,attnotnull,attidentity,attgenerated,attisdropped,attacl) ORDER BY attrelid,attnum)
 FROM pg_attribute WHERE attnum>0 AND attrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''triggers'',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE tgrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''constraints'',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE conrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''rules'',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE ev_class=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''defaults'',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d WHERE adrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])),
 ''policies'',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE polrelid=ANY(ARRAY[''native_turn_frames''::regclass,''native_turn_publication_work''::regclass,''native_turn_publication_events''::regclass,''native_turn_publication_seals''::regclass,''native_turn_publication_impossible''::regclass,''native_turn_publication_debt''::regclass])))'||') IS NOT DISTINCT FROM '||quote_literal(table_capture::text)||'::jsonb) AND (SELECT count(*)=2 AND bool_and(encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'')=expected.fingerprint) FROM (VALUES __PINS__) expected(id,fingerprint) JOIN pg_proc p ON p.oid=expected.id)';
 SELECT string_agg(format('(%L::regprocedure,%L::text)',p.oid::regprocedure::text,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',' ORDER BY p.proname) INTO pins
 FROM pg_proc p WHERE p.oid=ANY(ARRAY['native_turn_complete_publication()'::regprocedure,'native_turn_helpers_current()'::regprocedure]);
 IF (SELECT prosrc FROM pg_proc WHERE oid='native_turn_publication_contract()'::regprocedure) IS DISTINCT FROM replace(expected_body,'__PINS__',pins) THEN
  SELECT string_agg(format('(%L::regprocedure,%L::text)',p.oid::regprocedure::text,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',' ORDER BY p.proname DESC) INTO pins
  FROM pg_proc p WHERE p.oid=ANY(ARRAY['native_turn_complete_publication()'::regprocedure,'native_turn_helpers_current()'::regprocedure]);
  IF (SELECT prosrc FROM pg_proc WHERE oid='native_turn_publication_contract()'::regprocedure) IS DISTINCT FROM replace(expected_body,'__PINS__',pins)
  THEN RAISE EXCEPTION 'native_annotation_publication_contract_changed';END IF;
 END IF;
END $publication_tables$;
DO $reader_manifest$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid='public.native_turn_contract_helpers'::regclass
  AND c.relowner=(SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass) AND c.relkind='r' AND c.relpersistence='p' AND c.relrowsecurity AND NOT c.relforcerowsecurity
  AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>c.relowner OR a.grantor<>c.relowner)
  AND NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=c.oid AND attnum>0 AND (attacl IS NOT NULL OR attisdropped OR atthasdef OR attgenerated<>'' OR attidentity<>''))
  AND (SELECT jsonb_agg(jsonb_build_array(attname,atttypid::regtype::text,attnotnull) ORDER BY attnum)
   FROM pg_attribute WHERE attrelid=c.oid AND attnum>0)='[["signature","text",true],["fingerprint","text",true]]'::jsonb
  AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=c.oid)
  AND NOT EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=c.oid)
  AND NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=c.oid)
  AND (SELECT count(*) FILTER(WHERE contype='p')=1
   AND bool_and(contype='p' AND conkey=ARRAY[1]::smallint[] OR contype='n' AND conkey IN(ARRAY[1]::smallint[],ARRAY[2]::smallint[]))
   AND coalesce(jsonb_agg(to_jsonb(conkey) ORDER BY conkey) FILTER(WHERE contype='n'),'[]'::jsonb) IN('[]'::jsonb,'[[1],[2]]'::jsonb)
   FROM pg_constraint WHERE conrelid=c.oid))
 THEN RAISE EXCEPTION 'native_turn_query_manifest_changed';END IF;

 IF (SELECT count(*) FROM pg_index WHERE indrelid='public.native_turn_contract_helpers'::regclass)<>1
  OR NOT EXISTS(SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_opclass op ON op.oid=i.indclass[0]
   WHERE i.indrelid='public.native_turn_contract_helpers'::regclass AND i.indkey::text='1' AND i.indnatts=1 AND i.indnkeyatts=1
   AND i.indisprimary AND i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND i.indimmediate
   AND NOT i.indisexclusion AND NOT i.indnullsnotdistinct AND i.indexprs IS NULL AND i.indpred IS NULL
   AND i.indoption::text='0' AND i.indcollation[0]='pg_catalog."default"'::regcollation
   AND c.relam=(SELECT oid FROM pg_am WHERE amname='btree') AND op.opcmethod=c.relam
   AND op.opcnamespace='pg_catalog'::regnamespace AND op.opcintype='text'::regtype AND op.opcdefault)
  OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.native_turn_contract_helpers'::regclass AND attnum>0
   AND(attcollation<>'pg_catalog."default"'::regcollation OR attndims<>0 OR attinhcount<>0 OR NOT attislocal))
 THEN RAISE EXCEPTION 'native_annotation_reader_manifest_index_changed';END IF;
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE
 THEN RAISE EXCEPTION 'native_annotation_predecessor_contract_changed';END IF;
END $reader_manifest$;

-- Fixed legacy publication structure, before any catalog-derived guard rebuild.
-- Canonical code for all sixteen source/output trigger functions is independently
-- authenticated by the full native executable manifest. The optional cohort
-- trigger pair is authenticated separately by the exact compatibility branch.
DO $native_legacy_shape$
DECLARE queue_ids oid[]:=ARRAY['public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass];
 source_ids oid[]:=ARRAY['public.scope_derivations'::regclass,'public.scope_derivation_sources'::regclass];
 sequence_id oid:=pg_get_serial_sequence('public.native_field_dependency_work','id')::regclass;
 expected_owner oid:=(SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass);
 dependency_fk oid;actual jsonb;
BEGIN
 IF sequence_id IS DISTINCT FROM to_regclass('public.native_field_dependency_work_id_seq')
 OR EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=ANY(queue_ids||ARRAY[sequence_id]) AND (
  c.relowner<>expected_owner OR c.relnamespace<>'public'::regnamespace OR c.relpersistence<>'p' OR c.relispartition
  OR c.reloptions IS NOT NULL OR c.relforcerowsecurity
  OR c.oid=sequence_id AND(c.relkind<>'S' OR c.relrowsecurity)
  OR c.oid<>sequence_id AND(c.relkind<>'r' OR NOT c.relrowsecurity OR c.relam<>(SELECT oid FROM pg_am WHERE amname='heap'))
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault(CASE WHEN c.oid=sequence_id THEN 'S'::"char" ELSE 'r'::"char" END,c.relowner))) a
   WHERE a.grantee<>expected_owner OR a.grantor<>expected_owner OR a.is_grantable)))
 OR EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=ANY(queue_ids||ARRAY[sequence_id]) OR inhparent=ANY(queue_ids||ARRAY[sequence_id]))
 OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=ANY(queue_ids||ARRAY[sequence_id]))
 OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=ANY(queue_ids||ARRAY[sequence_id]))
 OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=ANY(queue_ids||ARRAY[sequence_id]))
 THEN RAISE EXCEPTION 'native_legacy_queue_relations_changed';END IF;
 SELECT jsonb_object_agg(c.relname,(SELECT jsonb_agg(jsonb_build_array(a.attname,a.atttypid::regtype::text,a.attnotnull,a.attidentity)
  ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0)) INTO actual FROM pg_class c WHERE c.oid=ANY(queue_ids);
 IF actual IS DISTINCT FROM '{"native_field_dependency_batches":[["transaction_id","bigint",true,""],["workspace_id","uuid",true,""],["derivation_id","uuid",true,""],["pending_events","integer",true,""],["queued_events","bigint",true,""],["fallback","boolean",true,""]],"native_field_dependency_work":[["id","bigint",true,"a"],["transaction_id","bigint",true,""],["workspace_id","uuid",true,""],["derivation_id","uuid",true,""],["source","jsonb",true,""],["fired","boolean",true,""],["processed","boolean",true,""]]}'::jsonb
 OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=ANY(queue_ids) AND attnum>0 AND
  (attisdropped OR attacl IS NOT NULL OR attgenerated<>'' OR atttypmod<>-1 OR attndims<>0 OR attinhcount<>0 OR NOT attislocal OR attcollation<>0))
 THEN RAISE EXCEPTION 'native_legacy_queue_columns_changed';END IF;
 SELECT jsonb_object_agg(c.relname||':'||a.attname,pg_get_expr(d.adbin,d.adrelid)) INTO actual
 FROM pg_attrdef d JOIN pg_class c ON c.oid=d.adrelid JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum WHERE d.adrelid=ANY(queue_ids);
 IF actual IS DISTINCT FROM '{"native_field_dependency_batches:queued_events":"1","native_field_dependency_batches:fallback":"false","native_field_dependency_work:fired":"false","native_field_dependency_work:processed":"false"}'::jsonb
 THEN RAISE EXCEPTION 'native_legacy_queue_defaults_changed';END IF;
 SELECT jsonb_object_agg(t.relname||':'||c.conname,pg_get_constraintdef(c.oid)) INTO actual
 FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid WHERE c.conrelid=ANY(queue_ids) AND c.contype<>'n';
 IF actual IS DISTINCT FROM '{"native_field_dependency_batches:native_field_dependency_batches_pending_events_check":"CHECK ((pending_events >= 0))","native_field_dependency_batches:native_field_dependency_batches_queued_events_check":"CHECK ((queued_events > 0))","native_field_dependency_batches:native_field_dependency_batches_pkey":"PRIMARY KEY (transaction_id, workspace_id, derivation_id)","native_field_dependency_work:native_field_dependency_work_pkey":"PRIMARY KEY (id)"}'::jsonb
 OR EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid=ANY(queue_ids) AND (
  c.connamespace<>'public'::regnamespace OR c.condeferrable OR c.condeferred OR NOT c.convalidated OR NOT c.conenforced
  OR c.conparentid<>0 OR NOT c.conislocal OR c.coninhcount<>0 OR c.confrelid<>0 OR c.contypid<>0 OR c.conperiod
  OR c.contype='n' AND(cardinality(c.conkey)<>1 OR c.conkey[1] NOT BETWEEN 1 AND CASE WHEN c.conrelid=queue_ids[1] THEN 6 ELSE 7 END)))
 OR (SELECT count(*) FROM pg_constraint WHERE conrelid=ANY(queue_ids) AND contype='n') NOT IN(0,13)
 THEN RAISE EXCEPTION 'native_legacy_queue_constraints_changed';END IF;
 SELECT jsonb_object_agg(c.relname,jsonb_build_object('table',t.relname,'keys',to_jsonb(ARRAY(SELECT unnest(i.indkey))),
  'unique',i.indisunique,'primary',i.indisprimary)) INTO actual FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid
 JOIN pg_class t ON t.oid=i.indrelid WHERE i.indrelid=ANY(queue_ids);
 IF actual IS DISTINCT FROM '{"native_field_dependency_batches_pkey":{"table":"native_field_dependency_batches","keys":[1,2,3],"unique":true,"primary":true},"native_field_dependency_work_pkey":{"table":"native_field_dependency_work","keys":[1],"unique":true,"primary":true},"native_field_dependency_work_batch":{"table":"native_field_dependency_work","keys":[2,3,4,1],"unique":false,"primary":false}}'::jsonb
 OR EXISTS(SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=ANY(queue_ids) AND (
  NOT i.indisvalid OR NOT i.indisready OR NOT i.indislive OR NOT i.indimmediate OR i.indisexclusion OR i.indnullsnotdistinct
  OR i.indnatts<>i.indnkeyatts OR i.indexprs IS NOT NULL OR i.indpred IS NOT NULL OR c.relam<>(SELECT oid FROM pg_am WHERE amname='btree')
  OR EXISTS(SELECT 1 FROM unnest(i.indcollation) x WHERE x<>0) OR EXISTS(SELECT 1 FROM unnest(i.indoption) x WHERE x<>0)
  OR EXISTS(SELECT 1 FROM unnest(i.indclass) WITH ORDINALITY op(class_id,position) LEFT JOIN pg_opclass cls ON cls.oid=op.class_id
   LEFT JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=i.indkey[(op.position-1)::integer]
   WHERE cls.opcnamespace IS DISTINCT FROM 'pg_catalog'::regnamespace OR NOT cls.opcdefault OR cls.opcmethod<>c.relam OR cls.opcintype IS DISTINCT FROM a.atttypid)))
 OR EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid=ANY(queue_ids) AND c.contype='p' AND NOT EXISTS(
  SELECT 1 FROM pg_index i WHERE i.indexrelid=c.conindid AND i.indrelid=c.conrelid AND i.indisprimary AND ARRAY(SELECT unnest(i.indkey))=c.conkey))
 THEN RAISE EXCEPTION 'native_legacy_queue_indexes_changed';END IF;
 IF (SELECT to_jsonb(s)-'seqrelid' FROM pg_sequence s WHERE seqrelid=sequence_id) IS DISTINCT FROM
 '{"seqtypid":"20","seqstart":1,"seqincrement":1,"seqmax":9223372036854775807,"seqmin":1,"seqcache":1,"seqcycle":false}'::jsonb
 OR (SELECT count(*) FROM pg_depend WHERE classid='pg_class'::regclass AND objid=sequence_id AND refclassid='pg_class'::regclass)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_depend WHERE classid='pg_class'::regclass AND objid=sequence_id AND objsubid=0
  AND refclassid='pg_class'::regclass AND refobjid=queue_ids[2] AND refobjsubid=1 AND deptype='i')
 THEN RAISE EXCEPTION 'native_legacy_queue_identity_changed';END IF;
 -- These preexisting shared evidence relations expose precisely CRUD to the
 -- application role; queue and publication working tables expose none.
 IF EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=ANY(source_ids) AND (c.relowner<>expected_owner
  OR c.relnamespace<>'public'::regnamespace OR c.relkind<>'r' OR c.relpersistence<>'p' OR NOT c.relrowsecurity OR c.relforcerowsecurity OR c.relispartition
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantor<>expected_owner OR a.is_grantable
   OR a.grantee<>expected_owner AND NOT(a.grantee=(SELECT oid FROM pg_roles WHERE rolname='app_user') AND a.privilege_type IN('SELECT','INSERT','UPDATE','DELETE')))
  OR (SELECT count(*) FROM aclexplode(c.relacl) a WHERE a.grantee=(SELECT oid FROM pg_roles WHERE rolname='app_user') AND a.privilege_type IN('SELECT','INSERT','UPDATE','DELETE'))<>4))
 OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=ANY(source_ids))
 OR EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=ANY(source_ids) OR inhparent=ANY(source_ids))
 THEN RAISE EXCEPTION 'native_legacy_evidence_relation_changed';END IF;
 SELECT jsonb_object_agg(c.relname||':'||t.tgname,pg_get_triggerdef(t.oid)) INTO actual
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE t.tgrelid=ANY(source_ids) AND NOT t.tgisinternal
 AND NOT(t.tgrelid IN('public.scope_derivations'::regclass,'public.scope_derivation_sources'::regclass) AND t.tgname='native_crm_cohort_invalidate');
 IF actual IS DISTINCT FROM '{"scope_derivation_sources:scope_derivation_sources_reference":"CREATE TRIGGER scope_derivation_sources_reference BEFORE INSERT OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION validate_scope_resource_reference()","scope_derivation_sources:workflow_derivation_dependencies":"CREATE CONSTRAINT TRIGGER workflow_derivation_dependencies AFTER INSERT OR UPDATE ON public.scope_derivation_sources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_workflow_derivation_dependencies()","scope_derivation_sources:workflow_derivation_receipts":"CREATE TRIGGER workflow_derivation_receipts BEFORE DELETE OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION guard_workflow_derivation_receipts()","scope_derivation_sources:page_derivation_dependencies":"CREATE CONSTRAINT TRIGGER page_derivation_dependencies AFTER INSERT OR UPDATE ON public.scope_derivation_sources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_page_derivation_dependencies()","scope_derivation_sources:page_derivation_receipts":"CREATE TRIGGER page_derivation_receipts BEFORE DELETE OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION guard_page_derivation_receipts()","scope_derivation_sources:crm_recovery_capture":"CREATE TRIGGER crm_recovery_capture AFTER INSERT OR DELETE OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION crm_capture_erasure_effect()","scope_derivation_sources:scope_derivation_sources_retention":"CREATE TRIGGER scope_derivation_sources_retention BEFORE INSERT OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION guard_external_source_derivation()","scope_derivation_sources:application_field_derivation_dependencies":"CREATE CONSTRAINT TRIGGER application_field_derivation_dependencies AFTER INSERT OR UPDATE ON public.scope_derivation_sources DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_application_field_dependencies()","scope_derivation_sources:application_field_sources_immutable":"CREATE TRIGGER application_field_sources_immutable BEFORE DELETE OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION guard_application_field_lineage()","scope_derivation_sources:session_context_lineage_source":"CREATE TRIGGER session_context_lineage_source BEFORE DELETE OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION guard_session_context_lineage()","scope_derivation_sources:application_field_dependency_work":"CREATE TRIGGER application_field_dependency_work AFTER INSERT OR UPDATE ON public.scope_derivation_sources FOR EACH ROW EXECUTE FUNCTION enqueue_native_field_dependency_work()","scope_derivations:scope_derivations_reference":"CREATE TRIGGER scope_derivations_reference BEFORE INSERT OR UPDATE ON public.scope_derivations FOR EACH ROW EXECUTE FUNCTION validate_scope_resource_reference()","scope_derivations:page_derivation_output_receipts":"CREATE TRIGGER page_derivation_output_receipts BEFORE DELETE OR UPDATE ON public.scope_derivations FOR EACH ROW EXECUTE FUNCTION guard_page_derivation_receipts()","scope_derivations:crm_recovery_capture":"CREATE TRIGGER crm_recovery_capture AFTER INSERT OR DELETE OR UPDATE ON public.scope_derivations FOR EACH ROW EXECUTE FUNCTION crm_capture_erasure_effect()","scope_derivations:application_field_derivations_immutable":"CREATE TRIGGER application_field_derivations_immutable BEFORE DELETE OR UPDATE ON public.scope_derivations FOR EACH ROW EXECUTE FUNCTION guard_application_field_lineage()","scope_derivations:session_context_lineage_output":"CREATE TRIGGER session_context_lineage_output BEFORE DELETE OR UPDATE ON public.scope_derivations FOR EACH ROW EXECUTE FUNCTION guard_session_context_lineage()"}'::jsonb OR EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=ANY(source_ids) AND NOT t.tgisinternal AND (
  NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=t.tgfoid AND p.pronamespace='public'::regnamespace)
  OR t.tgenabled<>'O' OR t.tgparentid<>0 OR t.tgargs<>''::bytea OR t.tgattr<>''::int2vector OR t.tgnargs<>0 OR t.tgqual IS NOT NULL
  OR t.tgoldtable IS NOT NULL OR t.tgnewtable IS NOT NULL OR t.tgconstrrelid<>0 OR t.tgconstrindid<>0
  OR t.tgconstraint<>0 AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.oid=t.tgconstraint AND c.contype='t'
   AND c.connamespace='public'::regnamespace AND c.conrelid=t.tgrelid AND c.conname=t.tgname
   AND c.condeferrable=t.tgdeferrable AND c.condeferred=t.tginitdeferred AND c.convalidated AND c.conenforced
   AND c.confrelid=0 AND c.conkey IS NULL AND c.confkey IS NULL AND c.conparentid=0)))
 THEN RAISE EXCEPTION 'native_legacy_evidence_trigger_changed';END IF;
 SELECT oid INTO dependency_fk FROM pg_constraint c WHERE conrelid='public.scope_derivation_sources'::regclass
 AND conname='scope_derivation_sources_workspace_id_derivation_id_fkey' AND contype='f'
 AND confrelid='public.scope_derivations'::regclass AND connamespace='public'::regnamespace AND convalidated AND conenforced
 AND NOT condeferrable AND NOT condeferred AND conislocal AND coninhcount=0 AND conparentid=0 AND NOT conperiod
 AND conkey=ARRAY[1,2]::smallint[] AND confkey=ARRAY[2,1]::smallint[] AND confupdtype='a' AND confdeltype='c' AND confmatchtype='s'
 AND pg_get_constraintdef(oid)='FOREIGN KEY (workspace_id, derivation_id) REFERENCES scope_derivations(workspace_id, id) ON DELETE CASCADE';
 IF dependency_fk IS NULL OR (SELECT count(*) FROM pg_trigger WHERE tgconstraint=dependency_fk)<>4
 OR EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint WHERE t.tgconstraint=dependency_fk AND (
  t.tgenabled<>'O' OR NOT t.tgisinternal OR t.tgdeferrable OR t.tginitdeferred OR t.tgparentid<>0
  OR t.tgnargs<>0 OR t.tgargs<>''::bytea OR t.tgattr<>''::int2vector OR t.tgqual IS NOT NULL OR t.tgoldtable IS NOT NULL OR t.tgnewtable IS NOT NULL
  OR t.tgconstrindid<>c.conindid OR t.tgconstrrelid<>CASE WHEN t.tgrelid=c.conrelid THEN c.confrelid ELSE c.conrelid END))
 OR (SELECT count(DISTINCT expected.name) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid
 JOIN (VALUES ('RI_FKey_check_ins',5,'scope_derivation_sources'),('RI_FKey_check_upd',17,'scope_derivation_sources'),
  ('RI_FKey_cascade_del',9,'scope_derivations'),('RI_FKey_noaction_upd',17,'scope_derivations')) expected(name,event_type,relation)
 ON p.proname=expected.name AND t.tgtype=expected.event_type AND t.tgrelid=to_regclass('public.'||expected.relation)
 WHERE t.tgconstraint=dependency_fk AND p.pronamespace='pg_catalog'::regnamespace
 AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='internal') AND p.prosrc=expected.name AND p.probin IS NULL)<>4
 THEN RAISE EXCEPTION 'native_legacy_reference_foreign_key_changed';END IF;
END $native_legacy_shape$;
DO $bridge$
DECLARE actual pg_proc;invalidator pg_proc;added pg_trigger;added_output pg_trigger;guard_name text;guard_names constant text[]:=ARRAY[
 'application_native_dependency_batch_helpers_current()','application_native_field_reference_helpers_current()'];
 original_bodies jsonb;original_metadata jsonb;body text;definition text;member_oids oid[];
 columns_sql text;row_sql text;comparisons text;catalog_shape jsonb;rows_sql text;
 shape_sql text;table_state jsonb;trigger_state jsonb;fk_query text;fk_state jsonb;
 dependency_tables text;own_tables text;reference_tables text;guard_index integer;phase integer;absent boolean;
 pins text:='';pin_count integer:=0;cohort oid:=to_regclass('public.native_crm_current_cohorts');
 invalidation_query text;invalidation_state jsonb;invalidation_guard text;prior_definition text;
BEGIN
 absent:=cohort IS NULL AND to_regprocedure('public.invalidate_native_crm_cohorts()') IS NULL
  AND to_regprocedure('public.application_publish_native_crm_cohort(uuid,text)') IS NULL
  AND to_regprocedure('public.publish_native_crm_entity_cohorts()') IS NULL
  AND to_regprocedure('public.initialize_native_crm_cohorts()') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname IN('native_crm_cohort_invalidate','native_crm_cohorts_insert','native_crm_cohorts_update','native_crm_cohorts_delete','native_crm_cohorts_initialize'));
 IF NOT absent THEN
 IF cohort IS NULL OR to_regprocedure('public.invalidate_native_crm_cohorts()') IS NULL THEN RAISE EXCEPTION 'native_invalidation_partial_state';END IF;
 SELECT * INTO STRICT invalidator FROM pg_proc WHERE oid='public.invalidate_native_crm_cohorts()'::regprocedure;
 IF invalidator.proowner IS DISTINCT FROM (SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass)
  OR invalidator.pronamespace<>'public'::regnamespace OR invalidator.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql')
  OR (to_jsonb(invalidator)-ARRAY['oid','prosrc','proowner','proacl','prolang','pronamespace']) IS DISTINCT FROM
  '{"probin":null,"procost":100,"prokind":"f","proname":"invalidate_native_crm_cohorts","prorows":0,"pronargs":0,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"2279","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}'::jsonb
  OR encode(sha256(convert_to(invalidator.prosrc,'UTF8')),'hex') IS DISTINCT FROM '9cae935f18e546ef4379800ad26da0342f17f843f6573d14936d815310c1846c'
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(invalidator.proacl,acldefault('f',invalidator.proowner))) a
   WHERE a.grantee<>invalidator.proowner OR a.grantor<>invalidator.proowner OR a.is_grantable OR a.privilege_type<>'EXECUTE')
 THEN RAISE EXCEPTION 'native_invalidation_executable_changed';END IF;
 SELECT * INTO added FROM pg_trigger WHERE tgrelid='public.scope_derivation_sources'::regclass AND tgname='native_crm_cohort_invalidate';
 IF added.oid IS NULL OR (to_jsonb(added)-ARRAY['oid','tgrelid','tgfoid']) IS DISTINCT FROM
  '{"tgargs":"\\x","tgattr":[],"tgname":"native_crm_cohort_invalidate","tgqual":null,"tgtype":29,"tgnargs":0,"tgenabled":"O","tgnewtable":null,"tgoldtable":null,"tgparentid":"0","tgconstraint":"0","tgdeferrable":false,"tgisinternal":false,"tgconstrindid":"0","tgconstrrelid":"0","tginitdeferred":false}'::jsonb
  OR added.tgfoid<>invalidator.oid
 THEN RAISE EXCEPTION 'native_invalidation_trigger_changed';END IF;
 SELECT * INTO added_output FROM pg_trigger WHERE tgrelid='public.scope_derivations'::regclass AND tgname='native_crm_cohort_invalidate';
 IF added_output.oid IS NULL OR (to_jsonb(added_output)-ARRAY['oid','tgrelid','tgfoid']) IS DISTINCT FROM
  '{"tgargs":"\\x","tgattr":[],"tgname":"native_crm_cohort_invalidate","tgqual":null,"tgtype":29,"tgnargs":0,"tgenabled":"O","tgnewtable":null,"tgoldtable":null,"tgparentid":"0","tgconstraint":"0","tgdeferrable":false,"tgisinternal":false,"tgconstrindid":"0","tgconstrrelid":"0","tginitdeferred":false}'::jsonb
  OR added_output.tgfoid<>invalidator.oid
 THEN RAISE EXCEPTION 'native_invalidation_trigger_changed';END IF;
 -- For these exact publication triggers TG_TABLE_NAME cannot enter the observation
 -- branch. Its sole SQL effect is eligible=false on this private plain table.
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=cohort AND c.relowner=invalidator.proowner
   AND c.relkind='r' AND c.relpersistence='p' AND c.relrowsecurity AND NOT c.relforcerowsecurity AND NOT c.relispartition
   AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>c.relowner OR a.grantor<>c.relowner OR a.is_grantable)) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 1';END IF;
 IF (SELECT jsonb_agg(jsonb_build_array(attname,atttypid::regtype::text,attnotnull) ORDER BY attnum) FROM pg_attribute WHERE attrelid=cohort AND attnum>0)
   IS DISTINCT FROM '[["workspace_id","uuid",true],["type_key","text",true],["eligible","boolean",true],["groups","jsonb",true]]'::jsonb THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 2';END IF;
 IF EXISTS(SELECT 1 FROM pg_attribute a WHERE attrelid=cohort AND attnum>0 AND (attacl IS NOT NULL OR attisdropped OR atthasdef OR attidentity<>'' OR attgenerated<>''
   OR attinhcount<>0 OR NOT attislocal OR attcollation IS DISTINCT FROM (SELECT typcollation FROM pg_type WHERE oid=a.atttypid))) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 3';END IF;
 IF EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=cohort) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 4';END IF;
 IF EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=cohort) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 5';END IF;
 IF EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=cohort OR inhparent=cohort) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 6';END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=cohort AND NOT tgisinternal) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 7';END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid=cohort)<>2 THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 8';END IF;
 IF EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid=cohort AND
   (t.tgtype NOT IN(5,17) OR t.tgenabled<>'O' OR NOT t.tgisinternal OR t.tgdeferrable OR t.tginitdeferred
    OR t.tgqual IS NOT NULL OR t.tgnargs<>0 OR t.tgargs<>''::bytea OR t.tgattr::text<>'' OR t.tgparentid<>0
    OR t.tgnewtable IS NOT NULL OR t.tgoldtable IS NOT NULL OR t.tgconstrrelid<>'public.workspaces'::regclass
    OR t.tgconstraint IS DISTINCT FROM (SELECT oid FROM pg_constraint WHERE conrelid=cohort AND contype='f')
    OR t.tgconstrindid IS DISTINCT FROM (SELECT conindid FROM pg_constraint WHERE conrelid=cohort AND contype='f')
    OR p.pronamespace<>'pg_catalog'::regnamespace OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname='internal')
    OR p.proname IS DISTINCT FROM CASE WHEN t.tgtype=5 THEN 'RI_FKey_check_ins' ELSE 'RI_FKey_check_upd' END
    OR p.prosrc IS DISTINCT FROM p.proname::text OR p.probin IS NOT NULL)) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 9';END IF;
 IF (SELECT count(*) FROM pg_index WHERE indrelid=cohort)<>1 THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 10';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE indrelid=cohort AND indisprimary AND indisunique AND indisvalid AND indisready AND indislive
   AND indnkeyatts=2 AND indnatts=2 AND indkey::text='1 2' AND indexprs IS NULL AND indpred IS NULL
   AND indimmediate AND NOT indnullsnotdistinct AND indoption::text='0 0'
   AND c.relkind='i' AND c.relowner=invalidator.proowner AND c.relam=(SELECT oid FROM pg_am WHERE amname='btree')
   AND indclass::text=(SELECT string_agg(oid::text,' ' ORDER BY CASE opcname WHEN 'uuid_ops' THEN 1 ELSE 2 END)
    FROM pg_opclass WHERE opcnamespace='pg_catalog'::regnamespace AND opcmethod=c.relam AND opcname IN('uuid_ops','text_ops'))
   AND indcollation::text=(SELECT string_agg(attcollation::text,' ' ORDER BY attnum) FROM pg_attribute WHERE attrelid=cohort AND attnum IN(1,2))) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 11';END IF;
 IF (SELECT count(*) FROM pg_constraint WHERE conrelid=cohort AND contype<>'n')<>3 THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 12';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=cohort AND contype='p' AND conkey=ARRAY[1,2]::smallint[] AND NOT condeferrable AND convalidated AND conenforced) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 13';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=cohort AND contype='f' AND conkey=ARRAY[1]::smallint[] AND confrelid='public.workspaces'::regclass
   AND confkey=ARRAY[1]::smallint[] AND confdeltype='c' AND confupdtype='a' AND confmatchtype='s' AND NOT condeferrable AND convalidated AND conenforced) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 14';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=cohort AND contype='c' AND conkey=ARRAY[2]::smallint[] AND convalidated AND conenforced
   AND pg_get_expr(conbin,conrelid)=$check$(type_key = ANY (ARRAY['person'::text, 'company'::text, 'deal'::text]))$check$) THEN RAISE EXCEPTION 'native_invalidation_write_dependency_changed: predicate 15';END IF;
 invalidation_query:=$capture$SELECT jsonb_build_object(
  'function',(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.invalidate_native_crm_cohorts()'::regprocedure),
  'publicationTriggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid IN('public.scope_derivations'::regclass,'public.scope_derivation_sources'::regclass)),
  'table',(SELECT jsonb_build_array(c.oid,c.relowner,c.relacl,c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity,c.relispartition) FROM pg_class c WHERE c.oid='public.native_crm_current_cohorts'::regclass),
  'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid='public.native_crm_current_cohorts'::regclass AND a.attnum>0),
  'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c WHERE c.conrelid='public.native_crm_current_cohorts'::regclass),
  'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid='public.native_crm_current_cohorts'::regclass),
  'triggerFunctions',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_proc p WHERE p.oid IN(SELECT tgfoid FROM pg_trigger WHERE tgrelid='public.native_crm_current_cohorts'::regclass)),
  'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE p.polrelid='public.native_crm_current_cohorts'::regclass),
  'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE r.ev_class='public.native_crm_current_cohorts'::regclass),
  'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid) FROM pg_index i WHERE i.indrelid='public.native_crm_current_cohorts'::regclass),
  'indexRelations',(SELECT jsonb_agg(jsonb_build_array(c.oid,c.relowner,c.relnamespace,c.relkind,c.relam,c.relacl) ORDER BY c.oid)
   FROM pg_class c JOIN pg_index i ON i.indexrelid=c.oid WHERE i.indrelid='public.native_crm_current_cohorts'::regclass),
  'inheritance',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.inhrelid,i.inhparent) FROM pg_inherits i WHERE i.inhrelid='public.native_crm_current_cohorts'::regclass OR i.inhparent='public.native_crm_current_cohorts'::regclass))$capture$;
 EXECUTE invalidation_query INTO invalidation_state;
 invalidation_guard:=' IF ('||invalidation_query||') IS DISTINCT FROM '||quote_literal(invalidation_state::text)||'::jsonb THEN RETURN false;END IF;';
 END IF;
 SELECT jsonb_object_agg(p.oid::regprocedure::text,p.prosrc),jsonb_object_agg(p.oid::regprocedure::text,to_jsonb(p)-'prosrc')
 INTO original_bodies,original_metadata FROM pg_proc p WHERE p.oid=ANY(ARRAY[guard_names[1]::regprocedure,guard_names[2]::regprocedure]);
 FOREACH guard_name IN ARRAY guard_names LOOP
  SELECT * INTO STRICT actual FROM pg_proc WHERE oid=guard_name::regprocedure;
  IF actual.proowner<>(SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass) OR actual.pronamespace<>'public'::regnamespace
   OR actual.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql')
   OR (to_jsonb(actual)-ARRAY['oid','prosrc','proowner','proacl','prolang','pronamespace','proname']) IS DISTINCT FROM
   '{"probin":null,"procost":100,"prokind":"f","prorows":0,"pronargs":0,"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}'::jsonb
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee<>actual.proowner OR a.grantor<>actual.proowner OR a.is_grantable OR a.privilege_type<>'EXECUTE')
  THEN RAISE EXCEPTION 'native_invalidation_guard_metadata_changed';END IF;
 END LOOP;
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION 'native_invalidation_turn_predecessor_changed';END IF;
 SELECT string_agg(quote_ident(attname),',' ORDER BY attnum),
  string_agg(format('format(%L,%s)', '%L::'||CASE WHEN attname='proacl' THEN 'jsonb' WHEN atttypid IN('pg_node_tree'::regtype,'oidvector'::regtype,'regproc'::regtype) THEN 'text' ELSE format_type(atttypid,atttypmod) END,
   CASE WHEN attname='proacl' THEN 'to_jsonb(p.proacl)' WHEN atttypid IN('pg_node_tree'::regtype,'oidvector'::regtype,'regproc'::regtype) THEN format('p.%I::text',attname) ELSE format('p.%I',attname) END),'||'',''||' ORDER BY attnum),
  string_agg(format('%s%s IS NOT DISTINCT FROM m.%I%s',CASE WHEN attname='proacl' THEN 'to_jsonb(p.proacl)' WHEN atttypid IN('pg_node_tree'::regtype,'oidvector'::regtype,'regproc'::regtype) THEN format('p.%I::text',attname) ELSE format('p.%I',attname) END,CASE WHEN attcollation<>0 OR atttypid IN('pg_node_tree'::regtype,'oidvector'::regtype,'regproc'::regtype) THEN ' COLLATE "C"' ELSE '' END,attname,CASE WHEN attcollation<>0 OR atttypid IN('pg_node_tree'::regtype,'oidvector'::regtype,'regproc'::regtype) THEN ' COLLATE "C"' ELSE '' END),' AND ' ORDER BY attnum),
  jsonb_agg(jsonb_build_array(attnum,attname,atttypid,atttypmod,attcollation) ORDER BY attnum)
 INTO columns_sql,row_sql,comparisons,catalog_shape
 FROM pg_attribute WHERE attrelid='pg_proc'::regclass AND attnum>0 AND NOT attisdropped;
 shape_sql:=$shape$SELECT jsonb_build_object(
 'relations',(SELECT jsonb_agg(jsonb_build_array(c.oid,c.relowner,c.relacl,c.relkind,c.relpersistence,c.relrowsecurity,c.relforcerowsecurity) ORDER BY c.oid)
  FROM pg_class c WHERE c.oid IN('public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass,
   pg_get_serial_sequence('public.native_field_dependency_work','id')::regclass)),
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attrelid,a.attnum,a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.atthasdef,a.attidentity,a.attgenerated,a.attisdropped,a.attacl) ORDER BY a.attrelid,a.attnum)
  FROM pg_attribute a WHERE a.attnum>0 AND a.attrelid IN('public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass)),
 'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.oid) FROM pg_attrdef d
  WHERE d.adrelid IN('public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass)),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p
  WHERE p.polrelid IN('public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass)),
 'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r
  WHERE r.ev_class IN('public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass)),
 'sequence',(SELECT to_jsonb(s) FROM pg_sequence s WHERE s.seqrelid=pg_get_serial_sequence('public.native_field_dependency_work','id')::regclass),
 'constraints',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.oid) FROM pg_constraint c
  WHERE c.conrelid IN('public.native_field_dependency_batches'::regclass,'public.native_field_dependency_work'::regclass)))$shape$;
 EXECUTE shape_sql INTO table_state;
 fk_query:=$fk$SELECT jsonb_build_object(
 'constraint',(SELECT to_jsonb(c) FROM pg_catalog.pg_constraint c WHERE c.conrelid='public.scope_derivation_sources'::regclass AND c.conname='scope_derivation_sources_workspace_id_derivation_id_fkey'),
